pub fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> Vec<f32> {
    let total_len = arr
        .len()
        .checked_add(values.len())
        .expect("length overflow when appending vectors");

    let mut result = Vec::with_capacity(total_len);

    // Move elements in order without cloning.
    result.extend(arr);
    result.extend(values);

    debug_assert_eq!(result.len(), total_len);
    result
}